{"content":"use anyhow::{Context, Result, bail};
use async_trait::async_trait;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::{BTreeMap, BTreeSet};
use std::sync::{
    Arc, RwLock,
    atomic::{AtomicBool, AtomicU64, AtomicUsize, Ordering},
};
use std::time::Duration;
use tokio::sync::{Mutex, Notify};
use tokio_util::sync::CancellationToken;

pub type ObjectId = String;
#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ObjectKind {
    Agent,
    Model,
    Tool,
    Skill,
    McpServer,
    Session,
    Task,
    Plugin,
    Custom,
}
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ObjectEnvelope {
    pub id: ObjectId,
    pub kind: ObjectKind,
    pub version: u32,
    pub description: String,
    #[serde(default)]
    pub dependencies: Vec<ObjectId>,
    #[serde(default)]
    pub capabilities: BTreeMap<String, Value>,
    #[serde(default)]
    pub labels: BTreeMap<String, String>,
    #[serde(default)]
    pub spec: Value,
}
impl ObjectEnvelope {
    pub fn new(id: impl Into<String>, kind: ObjectKind, description: impl Into<String>) -> Self {
        Self {
            id: id.into(),
            kind,
            version: 1,
            description: description.into(),
            dependencies: Vec::new(),
            capabilities: BTreeMap::new(),
            labels: BTreeMap::new(),
            spec: Value::Null,
        }
    }
}
#[derive(Clone)]
pub struct InvocationContext {
    pub session_id: String,
    pub trace_id: String,
    pub span_id: String,
    pub cancel: CancellationToken,
}
#[async_trait]
pub trait Object: Send + Sync {
    fn envelope(&self) -> ObjectEnvelope;
    async fn invoke(&self, method: &str, input: Value, context: InvocationContext)
    -> Result<Value>;
    async fn activate(&self) -> Result<()> {
        Ok(())
    }
    async fn dispose(&self) -> Result<()> {
        Ok(())
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ObjectIdentity {
    pub id: ObjectId,
    pub generation: u64,
    pub scope: String,
}
struct Entry {
    identity: ObjectIdentity,
    object: Arc<dyn Object>,
    accepting: AtomicBool,
    active: AtomicBool,
    in_flight: AtomicUsize,
    drained: Notify,
}
impl Entry {
    fn new(object: Arc<dyn Object>, generation: u64, scope: String) -> Self {
        Self {
            identity: ObjectIdentity {
                id: object.envelope().id,
                generation,
                scope,
            },
            object,
            accepting: AtomicBool::new(false),
            active: AtomicBool::new(false),
            in_flight: AtomicUsize::new(0),
            drained: Notify::new(),
        }
    }
}
/// A lease pins one generation; dropping it releases the drain barrier.
pub struct ObjectLease {
    entry: Arc<Entry>,
}
impl ObjectLease {
    pub fn identity(&self) -> &ObjectIdentity {
        &self.entry.identity
    }
    pub fn object(&self) -> &Arc<dyn Object> {
        &self.entry.object
    }
    pub async fn invoke(
        &self,
        method: &str,
        input: Value,
        context: InvocationContext,
    ) -> Result<Value> {
        self.entry.object.invoke(method, input, context).await
    }
}
impl Drop for ObjectLease {
    fn drop(&mut self) {
        if self.entry.in_flight.fetch_sub(1, Ordering::AcqRel) == 1 {
            self.entry.drained.notify_waiters();
        }
    }
}
/// Ordered middleware: before hooks may validate/transform; errors stop dispatch.
/// After hooks run in reverse order after either an object result or object error.
#[async_trait]
pub trait InvocationMiddleware: Send + Sync {
    async fn before(
        &self,
        _identity: &ObjectIdentity,
        _method: &str,
        _input: &mut Value,
        _context: &InvocationContext,
    ) -> Result<()> {
        Ok(())
    }
    async fn after(
        &self,
        _identity: &ObjectIdentity,
        _method: &str,
        _result: &Result<Value>,
