{"content":"//! 动态工作区 Hub：运行期按路径创建 / 重命名 / 摘除工作区，持久化到
//! `data_dir/workspaces.json`（temp+rename 原子写，与 projects.json 同模式）。
//!
//! 静态 `config.workspaces` 仍由 `attach_workspaces` nest 挂载；动态项由
//! `/w/{id}` 参数路由 dispatch（matchit 静态优先，两种挂载共存）。未知 id
//! 的请求委托给 `workspace_fallback`，保持尾斜杠 308 与 404 语义不变。

use crate::server::{ApiError, AppState};
type ApiResult<T> = std::result::Result<Json<T>, ApiError>;
use axum::Json;
use axum::extract::{Path, State};
use axum::http::{StatusCode, Uri};
use axum::response::{IntoResponse, Response};
use samho_core::AgentRuntime;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::{BTreeMap, BTreeSet};
use std::path::PathBuf;
use std::sync::Arc;
use tokio::sync::RwLock;
use tokio_util::sync::CancellationToken;
use tower::ServiceExt;

/// 动态工作区数量上限：每个工作区一个独立运行时（含连接池/MCP/技能扫描），需要限界。
const MAX_DYNAMIC_WORKSPACES: usize = 32;

pub(crate) type SharedRouter = axum::Router;

#[derive(Clone)]
pub(crate) struct WorkspaceEntry {
    pub(crate) runtime: Arc<AgentRuntime>,
    pub(crate) router: SharedRouter,
    pub(crate) terms: std::sync::Arc<crate::term::TermHub>,
    pub(crate) name: String,
}

/// 可被 AppState 共享的动态工作区注册表。
#[derive(Clone)]
pub(crate) struct HubState {
    pub(crate) dynamic: Arc<RwLock<BTreeMap<String, WorkspaceEntry>>>,
    registry_path: Arc<PathBuf>,
}

#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct WorkspaceRecord {
    id: String,
    name: String,
    path: PathBuf,
    data_dir: PathBuf,
}

impl HubState {
    pub(crate) fn new(registry_path: PathBuf) -> Self {
        Self {
            dynamic: Arc::new(RwLock::new(BTreeMap::new())),
            registry_path: Arc::new(registry_path),
        }
    }

    async fn snapshot(&self) -> Vec<(String, WorkspaceEntry)> {
        self.dynamic
            .read()
            .await
            .iter()
            .map(|(id, entry)| (id.clone(), entry.clone()))
            .collect()
    }

    async fn persist(&self, records: &[WorkspaceRecord]) -> Result<(), ApiError> {
        let payload = serde_json::to_vec_pretty(records).map_err(|e| {
            ApiError(
                StatusCode::INTERNAL_SERVER_ERROR,
                format!("序列化失败：{e}"),
            )
        })?;
        let parent = self
            .registry_path
            .parent()
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from("."));
        let temp = parent.join(format!(
            "workspaces.json.tmp-{}",
            uuid::Uuid::new_v4().simple()
        ));
        tokio::fs::create_dir_all(&parent).await.map_err(|e| {
            ApiError(
                StatusCode::INTERNAL_SERVER_ERROR,
                format!("data_dir 不可用：{e}"),
            )
        })?;
        tokio::fs::write(&temp, &payload)
            .await
            .map_err(|e| ApiError(StatusCode::INTERNAL_SERVER_ERROR, format!("写入失败：{e}")))?;
        tokio::fs::rename(&temp, self.registry_path.as_path())
            .await
            .map_err(|e| ApiError(StatusCode::INTERNAL_SERVER_ERROR, format!("发布失败：{e}")))?;
        Ok(())
    }

    /// 启动时恢复上次保存的动态工作区；条目损坏或运行时创建失败则告警并剔除。
    /// `root_shutdown` 用于派生每个工作区 AppState 的子取消令牌：根服务优雅
    /// 退出时随之取消动态工作区的 SSE/任务，不再让 graceful shutdown 无界等待。
    pub(crate) async fn load_saved(
        &self,
        base_config: samho_core::RuntimeConfig,
        root_shutdown: CancellationToken,
    ) {
        let Ok(bytes) = tokio::fs::read(self.registry_path.as_path()).await else {
            return;
        };
        let Ok(records) = serde_json::from_slice::<Vec<WorkspaceRecord>>(&bytes) else {
            tracing::warn!("workspaces.json 损坏，忽略动态工作区恢复");
            return;
        };
        let mut kept = Vec::new();
        for record in records {
            if !workspace_id_valid(&record.id)
                || record.id == "default"
                || self.dynamic.read().await.contains_key(&record.id)","end_line":120,"path":"crates/samho-cli/src/hub.rs","start_line":1,"total_lines":493,"truncated_lines":true}

{"content":"//! 任务类型（路由层级）→ 模型覆盖。
//!
//! 运行时的 `TaskRouter` 按复杂度解析出目标层级后，`RoleRouter` 查
//! `model_roles.json` 里该层级绑定的模型并强制改写 `profile.model`，
//! 使「不同类型的任务用不同模型」成为服务端语义（composer 里的显式
//! 模型选择仍然最优先）。每个工作区运行时持有独立的一份。

use std::collections::{BTreeMap, BTreeSet};
use std::path::PathBuf;
use std::sync::Arc;

use anyhow::{Context, Result};
use samho_core::{ModelDescriptor, ModelRouter, RouteDecision, TaskProfile, TaskRouter};
use serde_json::{Value, json};

/// 模型清单里作为「任务类型默认模型」的 id（不区分大小写，按顺序取第一个已配置者）。
/// deepseek-v4.1-flash 为当前默认 API；glm-5.3-flash 兼容旧版 `config init` 生成的配置。
const DEFAULT_MODEL_IDS: &[&str] = &["deepseek-v4.1-flash", "glm-5.3-flash"];

pub(crate) struct ModelRoles {
    /// None = 不落盘（测试用 detached 实例）。
    path: Option<PathBuf>,
    tiers: Vec<String>,
    /// tier id → 模型 id；空串表示该类型跟随自动路由。
    map: std::sync::RwLock<BTreeMap<String, String>>,
    default_model: Option<String>,
}

impl ModelRoles {
    pub(crate) fn detached() -> Arc<Self> {
        Arc::new(Self {
            path: None,
            tiers: Vec::new(),
            map: std::sync::RwLock::new(BTreeMap::new()),
            default_model: None,
        })
    }

    /// 读取持久化文件；缺失的层级补默认模型（DEFAULT_MODEL_IDS 中首个已配置者，
    /// 否则空 = 跟随自动路由）。未知层级与未知模型条目直接丢弃。
    pub(crate) fn load(path: PathBuf, config: &samho_core::RuntimeConfig) -> Self {
        let tiers: Vec<String> = config
            .routing
            .tiers
            .iter()
            .map(|tier| tier.id.clone())
            .collect();
        let model_ids: BTreeSet<String> =
            config.models.iter().map(|model| model.id.clone()).collect();
        let default_model = default_model_for(&config.models);
        let mut map = BTreeMap::new();
        if let Some(entries) = std::fs::read(&path)
            .ok()
            .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok())
            .and_then(|saved| saved.get("roles").and_then(Value::as_object).cloned())
        {
            for (tier, model) in entries {
                let model = model.as_str().unwrap_or_default().to_string();
                if tiers.contains(&tier) && (model.is_empty() || model_ids.contains(&model)) {
                    map.insert(tier, model);
                }
            }
        }
        for tier in &tiers {
            map.entry(tier.clone())
                .or_insert_with(|| default_model.clone().unwrap_or_default());
        }
        Self {
            path: Some(path),
            tiers,
            map: std::sync::RwLock::new(map),
            default_model,
        }
    }

    /// 某任务类型的模型覆盖；None 或空串 = 跟随自动路由。
    pub(crate) fn override_for(&self, tier: &str) -> Option<String> {
        let map = self.map.read().ok()?;
        map.get(tier).filter(|model| !model.is_empty()).cloned()
