#[derive(Parser)]
#[command(name = "samho", version, about = "面向 Object 的 Rust Agent 运行时")]
struct Cli {
    #[arg(long, global = true)]
    config: Option<PathBuf>,
    #[command(subcommand)]
    command: Command,
}

#[derive(Subcommand)]
enum Command {
    /// 在本地运行任务；默认 Provider 是明确标注的模拟器。
    Run(RunArgs),
    /// 在本机提供共享 Agent API 与网页工作台。
    Serve {
        #[arg(long)]
        bind: Option<String>,
    },
    /// 连接正在运行的 `samho serve` 服务。
    Tui {
        #[arg(long, default_value = "http://127.0.0.1:7432")]
        url: String,
    },
    /// 从已有会话的完整工具调用边界创建分支。
    Fork {
        session: String,
        #[arg(long)]
        cutoff: Option<usize>,
        #[arg(long)]
        title: Option<String>,
    },
    /// 查看运行时配置，不执行任务。
    Inspect,
    /// 创建完整且可编辑的运行时配置。
    Config {
        #[command(subcommand)]
        command: ConfigCommand,
    },
    /// 打印轨迹事件，或导出 JSONL。
    Replay {
        trace_id: Option<String>,
        #[arg(long)]
        export: Option<PathBuf>,
